var program;

function setup() {
  // pixelDensity(1);
  createCanvas(500, 500, WEBGL);
  // createCanvas(windowWidth, windowHeight,WEBGL);
  program = createShader(vert,frag);
}

function draw() {
  shader(program);
  // background(0);

	program.setUniform('u_resolution', [width, height]);
	program.setUniform('u_time', millis()/1000);
	program.setUniform('u_mouse', [map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),0,width,0,width*pixelDensity()), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))),0,height,width*pixelDensity(),0)]);

  quad(-1, -1, 1, -1, 1, 1, -1, 1);
}


// === Tab: vert ===
var vert=`

precision mediump float;
attribute vec3 aPosition;

void main(void){
  gl_Position = vec4(aPosition, 1.0);
}

`;

// === Tab: frag ===
var frag=`
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

vec2 random2( vec2 p ) {
    return fract(sin(vec2(dot(p,vec2(127.1,311.7)),dot(p,vec2(269.5,183.3))))*43758.5453);
}

vec3 random3(vec3 c) {
    float j = 4096.0*sin(dot(c,vec3(17.0, 59.4, 15.0)));
    vec3 r;
    r.z = fract(512.0*j);
    j *= .125;
    r.x = fract(512.0*j);
    j *= .125;
    r.y = fract(512.0*j);
    return r-0.5;
}

const float F3 =  0.3333333;
const float G3 =  0.1666667;
float snoise(vec3 p) {

    vec3 s = floor(p + dot(p, vec3(F3)));
    vec3 x = p - s + dot(s, vec3(G3));

    vec3 e = step(vec3(0.0), x - x.yzx);
    vec3 i1 = e*(1.0 - e.zxy);
    vec3 i2 = 1.0 - e.zxy*(1.0 - e);

    vec3 x1 = x - i1 + G3;
    vec3 x2 = x - i2 + 2.0*G3;
    vec3 x3 = x - 1.0 + 3.0*G3;

    vec4 w, d;

    w.x = dot(x, x);
    w.y = dot(x1, x1);
    w.z = dot(x2, x2);
    w.w = dot(x3, x3);

    w = max(0.6 - w, 0.0);

    d.x = dot(random3(s), x);
    d.y = dot(random3(s + i1), x1);
    d.z = dot(random3(s + i2), x2);
    d.w = dot(random3(s + 1.0), x3);

    w *= w;
    w *= w;
    d *= w;

    return dot(d, vec4(52.0));
}

void main() {
    vec2 st = gl_FragCoord.xy/u_resolution.xy;
    st.x *= u_resolution.x/u_resolution.y;
    vec3 color = vec3(.0);
    float grid = 10.;
    // Scale
    st *= grid;

    // Tile the space
    vec2 i_st = floor(st);
    vec2 f_st = fract(st);

    float m_dist = 1.;  // minimum distance
    for (int j= -1; j <= 1; j++ ) {
        for (int i= -1; i <= 1; i++ ) {
            // Neighbor place in the grid
            vec2 neighbor = vec2(float(i),float(j));

            // Random position from current + neighbor place in the grid
            vec2 offset = random2(i_st + neighbor);

            // Animate the offset
            offset = 0.5 + 0.5*sin(u_time + 6.2831*offset);

            // Position of the cell
            vec2 pos = neighbor + offset - f_st;

            // Cell distance
            float dist = length(pos);

            // Metaball it!
            // m_dist can set an initial threshold
            // 'm_dist*dist' basically multiplies the distance field around the cell(dist) by how close two cell are(m_dist)
            m_dist = min(m_dist, m_dist*dist);
        }
    }

    vec2 mpoint = u_mouse*grid/u_resolution;
    float dist = distance(mpoint, st) * .5;
    m_dist = min(m_dist, m_dist*dist);

    // Draw cells
    float cellR = m_dist;
    float cellG = m_dist;
    float cellB = m_dist;

    cellR += snoise(vec3(st*1., u_time*0.1))*0.06;
    cellG += snoise(vec3(st*1., u_time*0.1+.5))*0.06;
    cellB += snoise(vec3(st*1., u_time*0.1+1.))*0.06;

    cellR += snoise(vec3(st*100., u_time*0.1))*0.006;
    cellG += snoise(vec3(st*100., u_time*0.1))*0.006;
    cellB += snoise(vec3(st*100., u_time*0.1))*0.006;

    color.r += step(.1, cellR);
    color.g += step(.1, cellG);
    color.b += step(.1, cellB);

    gl_FragColor = vec4(1.1-color,1.0);
}


`

